<template><div class="portal-page"><header class="head"><div><h1>Citas</h1><p>Consulta y reserva citas con nuestro equipo</p></div><router-link to="/appointments/new" class="btn">Reservar cita</router-link></header><div class="card"><div class="toolbar"><input v-model="search" placeholder="Buscar por referencia, servicio o estado..." @input="debounceFetch"></div><div v-if="loading" class="state">Cargando...</div><template v-else><div v-if="!appointments.length" class="state">Aún no hay citas</div><div v-else class="table-wrap"><table><thead><tr><th>Referencia</th><th>Servicio</th><th>Fecha</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="a in appointments" :key="a.id"><td><router-link :to="`/appointments/${a.id}`">{{a.Ref}}</router-link></td><td>{{a.service_item}}</td><td>{{a.scheduled_date||'—'}}</td><td>{{statusLabel(a.status)}}</td><td><router-link :to="`/appointments/${a.id}`">Ver</router-link></td></tr></tbody></table></div><div v-if="totalRows>pageSize" class="pagination"><button :disabled="page<=1" @click="page--;fetch()">Anterior</button><span>Página {{page}} de {{totalPages}}</span><button :disabled="page>=totalPages" @click="page++;fetch()">Siguiente</button></div></template></div></div></template><script>export default{data(){return{appointments:[],search:'',page:1,pageSize:10,totalRows:0,loading:false,debounce:null}},computed:{totalPages(){return Math.ceil(this.totalRows/this.pageSize)||1}},mounted(){this.fetch()},methods:{async fetch(){this.loading=true;try{const{data}=await axios.get('/portal/appointments',{params:{page:this.page,limit:this.pageSize,search:this.search||undefined}});this.appointments=data.appointments||[];this.totalRows=data.totalRows||0}catch(_){}this.loading=false},debounceFetch(){clearTimeout(this.debounce);this.debounce=setTimeout(()=>{this.page=1;this.fetch()},300)},statusLabel(v){const s=(v||'').toLowerCase();return {completed:'Completada',delivered:'Entregada',ready:'Lista',pending:'Pendiente',intake:'Recepción',diagnostic:'Diagnóstico',quoted:'Cotizada',in_progress:'En progreso',approved:'Aprobada',cancelled:'Cancelada',declined:'Rechazada'}[s]||v||'Pendiente'}}}</script><style scoped>.head{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap;margin-bottom:1.25rem}.head h1{margin:0}.head p{margin:.2rem 0 0;color:var(--pc-text-muted)}.btn{background:var(--pc-primary);color:white;padding:.6rem .9rem;border-radius:8px;text-decoration:none}.card{background:var(--pc-surface);border:1px solid var(--pc-border);border-radius:var(--pc-radius);overflow:hidden}.toolbar{padding:1rem}.toolbar input{width:100%;padding:.65rem;border:1px solid var(--pc-border-strong);border-radius:8px;box-sizing:border-box}.state{padding:3rem;text-align:center;color:var(--pc-text-muted)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:.75rem 1rem;border-bottom:1px solid var(--pc-border);text-align:left}th{background:var(--pc-surface-alt)}a{color:var(--pc-primary)}.pagination{display:flex;justify-content:center;align-items:center;gap:1rem;padding:1rem}.pagination button{padding:.5rem 1rem;border:1px solid var(--pc-border-strong);border-radius:8px;background:var(--pc-surface)}</style>